INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 1, 106001, 1, 1, "キャル", 0, 0, -363, 7001, 0, 7, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 7002, 0, 7, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 7003, 0, 7, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 10001, 0, 10, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 1, 106001, 1, 1, "キャル", 0, 0, -363, 10002, 0, 10, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 10003, 0, 10, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 1, 106401, 2, 1, "シェフィ", 2104010, 0, -363, 10004, 0, 10, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -416.5, 12001, 0, 12, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 1, 106001, 1, 1, "キャル", 0, 0, -363, 13001, 0, 13, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 13002, 0, 13, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 1, 106401, 2, 1, "シェフィ", 2104010, 0, -363, 13003, 0, 13, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 13004, 0, 13, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 14001, 0, 14, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 1, 106401, 2, 1, "シェフィ", 2104010, 0, -363, 14002, 0, 14, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 14003, 0, 14, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 1, 106001, 1, 1, "キャル", 0, 0, -363, 14004, 0, 14, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 1, 105901, 1, 1, "コッコロ", 0, 0, -470, 15001, 0, 15, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 1, 106401, 2, 1, "シェフィ", 2104010, 0, -363, 16001, 0, 16, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 16002, 0, 16, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 1, 106001, 1, 1, "キャル", 0, 0, -363, 16003, 0, 16, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 16004, 0, 16, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 17002, 0, 17, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 1, 106001, 1, 1, "キャル", 0, 0, -363, 17004, 0, 25, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 17005, 0, 25, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 1, 106401, 2, 1, "シェフィ", 2104010, 0, -363, 17006, 0, 25, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 17007, 0, 25, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 1, 190801, 1, 1, "カリン", 0, 0, -363, 18001, 0, 18, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 1, 190801, 1, 2, "カリン", 0, 0, -363, 18002, 0, 18, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 1, 190801, 1, 3, "カリン", 0, 0, -470, 19001, 0, 19, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 1, 190801, 1, 4, "カリン", 0, 0, -470, 19002, 0, 19, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 1, 190801, 1, 5, "カリン", 0, 0, -470, 20001, 0, 20, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 1, 190801, 1, 6, "カリン", 0, 0, -470, 20002, 0, 20, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 1, 106001, 1, 1, "キャル", 0, 0, -363, 21001, 0, 21, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 21002, 0, 21, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 1, 106401, 2, 1, "シェフィ", 2104010, 0, -363, 21003, 0, 21, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 21004, 0, 21, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 1, 190801, 1, 1, "カリン", 0, 0, -430, 22001, 0, 22, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 1, 190801, 1, 2, "カリン", 0, 0, -430, 22002, 0, 22, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 1, 190801, 1, 3, "カリン", 0, 0, -430, 23001, 0, 23, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 1, 190801, 1, 4, "カリン", 0, 0, -430, 23002, 0, 23, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 2, 109001, 1, 1, "エリコ（バレンタイン）", 0, 8, -385, 24001, 10011, 24, 4.08, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 2, 109001, 1, 2, "エリコ（バレンタイン）", 0, 8, -385, 24002, 10011, 24, 5, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 2, 109001, 1, 3, "エリコ（バレンタイン）", 0, 8, -385, 24003, 10011, 24, 10.11, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 2, 109001, 1, 4, "エリコ（バレンタイン）", 0, 8, -385, 24004, 10011, 24, 4, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 2, 109001, 1, 5, "エリコ（バレンタイン）", 0, 8, -385, 24005, 10011, 24, 6, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 1, 109002, 1, 6, "エリコ（バレンタイン）", 0, 0, 0, 24006, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 1, 109002, 1, 7, "エリコ（バレンタイン）", 0, 0, 0, 24007, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 1, 109002, 1, 8, "エリコ（バレンタイン）", 0, 0, 0, 24008, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 1, 109002, 1, 9, "エリコ（バレンタイン）", 0, 0, 0, 24009, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 1, 109002, 1, 10, "エリコ（バレンタイン）", 0, 0, 0, 24010, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 2, 109101, 1, 1, "シズル（バレンタイン）", 0, 8, -385, 24011, 10011, 24, 2.12, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 2, 109101, 5, 2, "シズル（バレンタイン）", 0, 8, -385, 24012, 10011, 24, 4.19, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 4, 109101, 2, 3, "シズル（バレンタイン）", 0, 8, -385, 24013, 10011, 24, 2.3, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 1, 109102, 1, 4, "シズル（バレンタイン）", 0, 0, 0, 24014, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 2, 109101, 5, 5, "シズル（バレンタイン）", 0, 8, -385, 24015, 10011, 24, 5.23, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 1, 109102, 1, 6, "シズル（バレンタイン）", 0, 0, 0, 24016, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 2, 109101, 1, 7, "シズル（バレンタイン）", 0, 8, -385, 24017, 10011, 24, 5.01, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 1, 109102, 1, 8, "シズル（バレンタイン）", 0, 0, 0, 24018, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 1, 109102, 1, 9, "シズル（バレンタイン）", 0, 0, 0, 24019, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 1, 109102, 1, 10, "シズル（バレンタイン）", 0, 0, 0, 24020, 10011, 24, 0, "2019/01/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 1, 106401, 2, 1, "シェフィ", 2104010, 0, -363, 26001, 0, 26, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 26002, 0, 26, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 1, 106001, 1, 1, "キャル", 0, 0, -363, 26003, 0, 26, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 26004, 0, 26, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 1, 106401, 2, 1, "シェフィ", 2104010, 0, -363, 27001, 0, 27, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 27002, 0, 27, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 1, 106001, 1, 1, "キャル", 0, 0, -363, 27003, 0, 27, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 27004, 0, 27, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 1, 190801, 1, 1, "カリン", 0, 0, -363, 28001, 0, 28, 0, "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 1, 190801, 1, 2, "カリン", 0, 0, -363, 28002, 0, 28, 0, "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 1, 190801, 1, 3, "カリン", 0, 0, -409, 29001, 0, 29, 0, "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 1, 190801, 1, 4, "カリン", 0, 0, -409, 29002, 0, 29, 0, "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 1, 190801, 1, 5, "カリン", 0, 0, -409, 30001, 0, 30, 0, "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 1, 190801, 1, 6, "カリン", 0, 0, -409, 30002, 0, 30, 0, "2019/09/24 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 1, 190801, 1, 7, "カリン", 0, 0, -409, 31001, 0, 31, 0, "2019/10/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 1, 190801, 1, 8, "カリン", 0, 0, -409, 31002, 0, 31, 0, "2019/10/31 12:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2020/01/04 4:59:59", "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 1, 190801, 1, 1, "カリン", 0, 0, -409, 32001, 0, 32, 0, "2019/12/20 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2020/01/04 4:59:59", "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 1, 190801, 1, 2, "カリン", 0, 0, -409, 32002, 0, 32, 0, "2019/12/20 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2020/01/04 4:59:59", "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 1, 190801, 1, 3, "カリン", 0, 0, -409, 33001, 0, 33, 0, "2019/12/20 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2020/01/04 4:59:59", "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 1, 190801, 1, 4, "カリン", 0, 0, -409, 33002, 0, 33, 0, "2019/12/20 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2020/01/10 11:59:59", "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 1, 190801, 1, 5, "カリン", 0, 0, -409, 34001, 0, 34, 0, "2020/01/04 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2020/01/10 11:59:59", "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 1, 190801, 1, 6, "カリン", 0, 0, -409, 34002, 0, 34, 0, "2020/01/04 5:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 2, 105801, 1, 1, "ペコリーヌ", 0, 0, -458, 38001, 0, 38, 5.3, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 2, 105801, 1, 2, "ペコリーヌ", 0, 0, -458, 38002, 0, 38, 6.5, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2020/04/08 23:59:59", "", 3, 105801, 3, 0, "ペコリーヌ", 0, 9999, 9999, 39005, 0, 39, 0, "2020/04/01");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 1, 190801, 1, 2, "カリン", 0, 0, -430, 40001, 0, 40, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 1, 106401, 1, 1, "シェフィ", 2104010, 0, -363, 41001, 0, 41, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 41002, 0, 41, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 1, 106001, 1, 1, "キャル", 0, 0, -363, 41003, 0, 41, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 41004, 0, 41, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 1, 105901, 1, 1, "コッコロ", 0, 0, -416.5, 42001, 0, 42, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 1, 106401, 1, 1, "シェフィ", 2104010, 0, -416.5, 42002, 0, 42, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -416.5, 42003, 0, 42, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 1, 106001, 1, 1, "キャル", 0, 0, -416.5, 42004, 0, 42, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 1, 105801, 1, 1, "ペコリーヌ", 0, 0, -363, 43001, 0, 43, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 1, 105901, 1, 1, "コッコロ", 0, 0, -363, 43002, 0, 43, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 1, 106001, 1, 1, "キャル", 0, 0, -363, 43003, 0, 43, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 1, 123001, 1, 1, "アメス", 0, 0, -416.5, 43004, 0, 44, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 1, 123001, 1, 2, "アメス", 0, 0, -416.5, 43005, 0, 44, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 2, 123001, 1, 3, "アメス", 0, 0, -416.5, 43006, 0, 45, 5.79, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 1, 123001, 1, 1, "アメス", 0, 0, -371.5, 46001, 0, 46, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 2, 104901, 2, 1, "シズル", 0, 0, -416.5, 47001, 0, 47, 0, "2015/12/17 15:00:00");
INSERT INTO `v1_20e94a1fdc1ae90412eee50b093eb6d68a5c93d7a4619c00965c7db7dcef99e0` VALUES ("2030/12/17 14:59:59", "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 2, 101101, 1, 1, "リノ", 0, 0, -416.5, 47002, 0, 47, 9.32, "2015/12/17 15:00:00");
